from pathlib import Path
import json,base64
r=Path(__file__).parent
assets={n:r/'rapid-pickup-v1'/f'{n}.png' for n in ['open','half','closed','turn','hug']}
assets.update(turn20=r/'rapid-pickup-v3/turn20.png',precontact=r/'rapid-pickup-v2/precontact.png',stool=r/'canonical-registered-v1/stool-world-candidate-v2.png',seated=r.parent/'seated-work/canonical-lid-v1/closed-canonical-candidate.png',seatedOpen=r.parent/'shared/seated-open-canonical-alpha-v1.png',contact=r/'canonical-static-v1/closed.png',release=r/'canonical-static-v2/lap-release.png',settle=r/'closed-handoff-v1/near-settled.png',hugPrecontact=r/'canonical-registered-v1/preland-no-stool-white-alpha.png',hugContact=r/'canonical-registered-v1/contact-skirt-restored-v3.png',hugSettle=r/'canonical-registered-v2/contact-settle-bridge-white-alpha.png',seatedHug=r/'canonical-static-v1/hug.png',seatedTurn=r/'canonical-static-v1/turn.png',seatedGrip=r/'canonical-static-v1/grip-lift-white.png')
data={k:'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode() for k,p in assets.items()}
html='''<!doctype html><meta charset=utf-8><title>Interactive relocation — authored frame candidate</title><style>body{background:#182431;color:#eee;font:15px system-ui;margin:20px}canvas{background:#26384b;touch-action:none;border:1px solid #8aa}button{margin:5px;padding:8px}</style><h2>Internal interactive relocation candidate</h2><p>Drag character freely. Release during closure, transfer or landing; grab again before settling. Pointer follows immediately. Real drawings only, no character crossfade. Motion/contact/art continuity remains under review.</p><button id=reset>Reset open seated</button><button id=slow>Slow/normal</button><div id=status></div><canvas id=c width=1000 height=660></canvas><script>const sources=DATA,imgs={};for(const[k,v]of Object.entries(sources)){imgs[k]=new Image;imgs[k].src=v}const ctx=c.getContext('2d');let root={x:100,y:90},old={...root,a:0},target={...root,a:0},pose='seatedOpen',queue=[],age=0,held=false,offset={x:0,y:0},speed=1,last=performance.now(),history=[];function record(e){history.push(e);history=history.slice(-12)}function plan(a){queue=a.map(([p,d])=>({p,d}));age=0;if(queue.length)pose=queue[0].p}const up=['open','half','closed','turn20','turn','hug'];function pickup(){const idx=up.indexOf(pose);if(idx>=0){plan(up.slice(idx).map(p=>[p,p==='hug'?150:65]));return}if(['hugPrecontact','hugContact','hugSettle','seatedHug'].includes(pose)){plan([['hugPrecontact',55],['hug',100]]);return}if(pose==='seatedOpen'){plan(up.map(p=>[p,p==='hug'?150:65]));return}plan([['closed',55],['turn20',65],['turn',65],['hug',100]])}function release(){if(['open','half','closed','turn20'].includes(pose)){const close=pose==='open'?[['half',55],['closed',55]]:pose==='half'?[['closed',55]]:pose==='turn20'?[['closed',65]]:[];plan([...close,['precontact',90],['contact',80],['release',80],['settle',70],['seated',300]])}else{plan([['hug',55],['hugPrecontact',90],['hugContact',80],['hugSettle',80],['seatedHug',70],['seatedTurn',65],['seatedGrip',65],['contact',70],['release',70],['settle',70],['seated',300]])}}function pt(e){const b=c.getBoundingClientRect();return{x:(e.clientX-b.left)*1000/b.width,y:(e.clientY-b.top)*660/b.height}}c.onpointerdown=e=>{const p=pt(e);if(p.x<root.x||p.x>root.x+512||p.y<root.y||p.y>root.y+512)return;c.setPointerCapture(e.pointerId);held=true;offset={x:p.x-root.x,y:p.y-root.y};old={x:target.a?target.x:root.x,y:target.a?target.y:root.y,a:pose.startsWith('seated')?1:target.a};target.a=0;record('grab from '+pose);pickup()};c.onpointermove=e=>{if(!held)return;const p=pt(e);root.x=Math.max(-60,Math.min(550,p.x-offset.x));root.y=Math.max(-30,Math.min(148,p.y-offset.y))};c.onpointerup=e=>{if(!held)return;held=false;target={...root,a:0};record('release from '+pose);release()};c.onpointercancel=c.onpointerup;reset.onclick=()=>{root={x:100,y:90};old={...root,a:0};target={...root,a:0};pose='seatedOpen';queue=[];held=false;history=[]};slow.onclick=()=>speed=speed===1?.25:1;function draw(t){const dt=Math.min(100,t-last)*speed;last=t;age+=dt;if(queue.length&&age>=queue[0].d){age-=queue[0].d;queue.shift();if(queue.length)pose=queue[0].p}old.a=Math.max(0,old.a-dt/150);if(!held&&queue.length)target.a=Math.min(1,target.a+dt/100);ctx.clearRect(0,0,1000,660);for(const s of [old,target])if(s.a&&imgs.stool.complete&&!(s===target&&['contact','release','settle','seated','seatedHug','seatedTurn','seatedGrip'].includes(pose))){ctx.globalAlpha=s.a;ctx.drawImage(imgs.stool,s.x,s.y)}ctx.globalAlpha=1;if(imgs[pose].complete)ctx.drawImage(imgs[pose],root.x,root.y);document.getElementById('status').textContent=(held?'HELD':'RELEASED')+' | '+pose+' | root '+Math.round(root.x)+','+Math.round(root.y)+' | '+history.join(' → ');requestAnimationFrame(draw)}requestAnimationFrame(draw)</script>'''.replace('DATA',json.dumps(data))
(r/'reviews/interactive-relocation-v1.html').write_text(html)
(r/'reviews/interactive-relocation-contract-v1.json').write_text(json.dumps({'stage':'interactive-motion-candidate','rootFollowsPointerImmediately':True,'stoolLayer':'world anchored; opacity only','releasePolicy':'from actual current authored grip; close lap branch does not detour through hug','regrabPolicy':'contact pending can reverse to airborne with secure grip','knownGaps':['head/skirt junction across old hugging landing family','directions not covered','art cadence not accepted','target stool must not double draw under embedded seated sprites']},indent=2))
